window.T21_DASHBOARD_UNITS = [{"unit":1,"theme":"apologize – emotional","cards":[{"w":"apologize","p":"v.","d":"to express regret or say sorry for doing something wrong","c":"道歉；認錯","s":"You really should apologize to that man for stepping on his foot on the bus.","t":"你在公車上踩到了那位男士的腳，真的應該向他道歉。"},{"w":"capable","p":"adj.","d":"having the ability, fitness, or quality necessary to do something","c":"有能力的；能夠…的","s":"This company needs a capable person for the position as it requires strong leadership.","t":"這間公司需要一位有能力的人來擔任該職位，因為這需要堅強的領導力。"},{"w":"cheek","p":"n.","d":"either side of the face below the eye and above the jaw","c":"臉頰；面頰","s":"Julie's nose and cheeks were bright red from being out in the freezing cold.","t":"茱莉因為在刺骨的嚴寒中待了太久，鼻子和臉頰都紅通通的。"},{"w":"civil","p":"adj.","d":"relating to ordinary citizens and their concerns; courteous and polite","c":"公民的；民事的；有禮貌的","s":"Civil servants are dedicated people who work for the government rather than the military.","t":"公務員是為政府而非軍方服務的盡責工作人員。"},{"w":"comfort","p":"n./v.","d":"a state of physical ease; to soothe someone in grief or distress","c":"舒適；安慰 (n.)；安慰 (v.)","s":"Guest comfort is the top priority for all dedicated staff working at this luxury hotel.","t":"賓客的舒適感是這家豪華飯店所有盡責員工的最高準則。"},{"w":"countable","p":"adj.","d":"able to be counted, especially used of nouns in grammar","c":"可數的","s":"The English teacher asked students to point out all the countable nouns written on the board.","t":"英文老師要求學生指出黑板上寫的所有可數名詞。"},{"w":"dump","p":"v./n.","d":"to deposit or discard carelessly; a site for depositing garbage","c":"傾倒；丟下；拋棄 (v.)；垃圾場 (n.)","s":"The careless children dumped their heavy school bags and winter coats straight onto the living room floor.","t":"粗心大意的小孩一回到家就把沉重的書包和冬衣直接扔在客廳地板上。"},{"w":"emotional","p":"adj.","d":"relating to a person's feelings; expressing intense emotion","c":"情緒的；情感的；激動的","s":"Brian demonstrated remarkable emotional strength and patience when his beloved wife fell seriously ill.","t":"當心愛的妻子病重時，布萊恩展現了非凡的精神／情感力量與無比的耐心。"}]},{"unit":2,"theme":"gasoline – lemonade","cards":[{"w":"gasoline","p":"n.","d":"a refined petroleum liquid used as fuel for motor vehicles","c":"汽油 (縮寫為 gas)","s":"Drivers should fill the tank with gasoline before embarking on a long journey across the desert.","t":"在橫越沙漠的長途旅行之前，駕駛人應該先把油箱加滿汽油。"},{"w":"grasp","p":"v./n.","d":"to seize and hold firmly; to comprehend or understand fully","c":"抓緊；握住；理解 (v.)；緊握；掌握 (n.)","s":"New students often struggle to grasp the complicated concepts introduced in advanced physics.","t":"新生往往很難理解／掌握高等物理學中介紹的複雜抽象概念。"},{"w":"horrible","p":"adj.","d":"causing horror; very unpleasant, shocking, or disagreeable","c":"可怕的；糟糕的；極令人討厭的","s":"Because the violent crime was so horrible, the judge sentenced the defendant to life imprisonment.","t":"因為那起暴力罪行極其駭人殘暴，法官判處被告終身監禁。"},{"w":"immediate","p":"adj.","d":"occurring or done at once; direct and without delay","c":"立即的；直接的；刻不容緩的","s":"The powerful painkiller had an immediate effect on the patient, bringing relief within minutes.","t":"這款強力止痛藥對病患產生了立竿見影的療效，數分鐘內便帶來舒緩。"},{"w":"inner","p":"adj.","d":"situated inside or further in; relating to the mind or spirit","c":"內部的；內心的","s":"The soft inner lining of the winter jacket provides excellent insulation against icy winds.","t":"這件冬季夾克柔軟的內襯提供了絕佳的隔熱保暖效果，可抵禦刺骨寒風。"},{"w":"innocent","p":"adj.","d":"not guilty of a crime or offense; simple and harmless","c":"清白的；無罪的；純真的","s":"Although the suspect was questioned for hours, convincing evidence proved he was completely innocent.","t":"儘管嫌犯被訊問了數小時，確鑿的證據證明他是完全清白無罪的。"},{"w":"leisure","p":"n.","d":"time free from work or duties, spent in relaxation or hobbies","c":"休閒；空閒；悠閒","s":"After forty years of tireless corporate work, the executive plans to retire to a life of leisure.","t":"在企業不知疲倦地工作四十年後，這位高階主管打算退休享受悠閒的慢活人生。"},{"w":"lemonade","p":"n.","d":"a refreshing drink made from lemon juice, sugar, and water","c":"檸檬水","s":"On a sweltering summer afternoon, nothing is more refreshing than a tall glass of icy lemonade.","t":"在悶熱潮濕的炎炎夏日午後，沒有什麼比一大杯冰涼的檸檬水更能消暑解渴了。"}]},{"unit":3,"theme":"litter – portrait","cards":[{"w":"litter","p":"n./v.","d":"trash left lying in an open place; to scatter garbage untidily","c":"垃圾；廢棄物 (n.)；亂丟垃圾；散落 (v.)","s":"The public beach was heavily covered in litter because careless tourists failed to clean up.","t":"這座公共海灘滿地都是垃圾，因為粗心的遊客離開前沒有清理乾淨。"},{"w":"mess","p":"n./v.","d":"a dirty or untidy state; to make something untidy or disorganized","c":"凌亂；混亂；困境 (n.)；弄亂；搞砸 (v.)","s":"David took an entire afternoon to clean his apartment because the living room was in an awful mess.","t":"大衛花了整整一個下午打掃公寓，因為客廳實在是凌亂不堪／一團糟。"},{"w":"mosquito","p":"n.","d":"a small flying insect whose female bites humans and animals for blood","c":"蚊子 (複數為 mosquitoes / mosquitos)","s":"An itchy mosquito bite on my left ankle swelled up and bothered me throughout the humid evening.","t":"左腳踝上被蚊子叮咬的發癢腫塊腫了起來，整晚潮濕悶熱中困擾著我。"},{"w":"muscle","p":"n.","d":"a band of fibrous tissue that produces motion in animal bodies","c":"肌肉；力量","s":"My leg muscles felt extremely sore after running uphill for an hour without proper stretching.","t":"在沒有做適當拉筋的情況下往上坡跑了一小時，我的腿部肌肉感到無比痠痛。"},{"w":"owe","p":"v.","d":"to have an obligation to pay money or show gratitude to someone","c":"欠 (錢、情)；歸功於","s":"Nathan has been avoiding me at work because he still owes me fifty dollars from last week.","t":"內森在公司一直躲著我，因為他上週跟我借的五十塊錢到現在還欠著沒還。"},{"w":"pea","p":"n.","d":"a small, round green seed eaten as a vegetable","c":"豌豆","s":"For dinner at the steakhouse, she ordered a grilled ribeye steak with a savory side of steamed peas.","t":"在牛排館享用晚餐時，她點了一份炭烤肋眼牛排搭配美味的清蒸豌豆佐菜。"},{"w":"pollute","p":"v.","d":"to contaminate the environment with harmful or poisonous substances","c":"污染；弄髒","s":"Smoky exhaust fumes from millions of motor vehicles continue to pollute urban air quality.","t":"數百萬輛機動車排放的濃煙廢氣，持續惡化並污染城市的空氣品質。"},{"w":"portrait","p":"n.","d":"a painting, drawing, or photograph of a person, especially the face","c":"肖像；人像畫；生動描繪","s":"The historic museum displays a magnificent oil portrait of the royal queen painted in the seventeenth century.","t":"這間歷史博物館陳列了一幅十七世紀繪製的皇家女王壯麗油畫肖像。"}]},{"unit":4,"theme":"puppet – violence","cards":[{"w":"puppet","p":"n.","d":"a movable model of a person or animal manipulated by strings or hand","c":"木偶；玩偶；傀儡","s":"Alice used colorful handmade puppets to captivate young children during the library storytelling session.","t":"愛麗絲在圖書館說故事活動中，使用色彩繽紛的手工木偶吸引了年幼孩子們的注意。"},{"w":"rot","p":"v./n.","d":"to decay or cause to decay through the action of bacteria or fungi","c":"腐爛；腐壞 (v.)；腐爛 (n.)","s":"If you leave ripe peaches in a damp bag, they will quickly begin to rot and attract fruit flies.","t":"如果你把熟桃子留在潮濕的袋子裡，它們很快就會開始腐爛並引來果蠅。"},{"w":"semester","p":"n.","d":"a half-year term in a school or college, typically lasting 15–18 weeks","c":"學期 (一學年兩學期制)","s":"Linda decided to enroll in an intensive statistics course during the upcoming spring semester.","t":"琳達決定在即將到來的春季學期修習一門密集的高等統計學課程。"},{"w":"sin","p":"n./v.","d":"an immoral act considered a transgression against divine law","c":"罪過；罪惡 (n.)；犯罪；背離道德 (v.)","s":"Devout believers visit church confessionals regularly to seek spiritual forgiveness from their sins.","t":"虔誠的信徒定期前往教堂告解室，尋求自己罪過的心靈寬恕。"},{"w":"spite","p":"n./v.","d":"a desire to hurt, annoy, or offend someone; malice","c":"惡意；怨恨 (n.)；刁難；激怒 (v.)","s":"I am convinced that my jealous neighbor damaged my car paint entirely out of spite.","t":"我深信我那嫉妒的鄰居完全是出於惡意才故意刮傷我的車漆。"},{"w":"tasty","p":"adj.","d":"having a pleasant, savory flavor; delicious","c":"美味的；可口的","s":"The night market vendor served amazingly tasty fried dumplings accompanied by spicy dipping sauce.","t":"夜市攤販供應了極其美味可口的煎餃，搭配特製香辣沾醬。"},{"w":"ton","p":"n.","d":"a unit of weight equal to 2,000 pounds (US) or 1,000 kg (metric)","c":"公噸；大量；許多 (口語)","s":"Marine biologists spotted an enormous blue whale estimated to weigh at least one hundred tons.","t":"海洋生物學家發現了一頭估計重達至少一百公噸的巨大藍鯨。"},{"w":"violence","p":"n.","d":"behavior involving physical force intended to hurt, damage, or kill","c":"暴力；狂暴","s":"International organizations are working tirelessly to eliminate domestic violence against women and children.","t":"國際組織正不知疲倦地努力消除針對婦女與兒童的家庭暴力。"}]},{"unit":5,"theme":"wax – wrap","cards":[{"w":"wax","p":"n./v.","d":"a sticky yellowish substance used for candles; to polish with wax","c":"蠟 (n.)；上蠟；打蠟；給…除毛 (v.)","s":"Jason spent his Sunday afternoon waxing his vintage sports car until its red paint shone brilliantly.","t":"傑森花了他的週日下午給他的老爺跑車打蠟，直到紅色烤漆煥發出耀眼光澤。"},{"w":"weapon","p":"n.","d":"a thing designed or used for inflicting bodily harm or physical damage","c":"武器；手段","s":"Strict aviation regulations forbid passengers from carrying dangerous weapons such as firearms onto flights.","t":"嚴格的航空法規禁止乘客將槍械等危險武器攜帶上飛機。"},{"w":"weep","p":"v./n.","d":"to shed tears as an expression of grief, sorrow, or joy","c":"哭泣；流淚 (v. wept, wept)；抽泣 (n.)","s":"The emotional drama was so profoundly heartbreaking that nearly everyone in the theater began to weep.","t":"這部感人戲劇實在太過令人心碎，以至於戲院裡幾乎每個人都開始流淚痛哭。"},{"w":"whip","p":"v./n.","d":"to beat with a lash; to beat cream or eggs into a light froth","c":"鞭打；攪打 (v.)；鞭子 (n.)","s":"To finish the dessert, the pastry chef whipped heavy organic cream with pure vanilla sugar until fluffy.","t":"為了完成甜點，西點主廚將有機重鮮奶油與純香草糖攪打至蓬鬆綿密。"},{"w":"whistle","p":"n./v.","d":"a small instrument producing a sound; to make a clear high pitch","c":"口哨；笛子 (n.)；吹口哨；吹哨呼叫 (v.)","s":"The soccer referee blew his loud metal whistle to signal the end of the thrilling championship match.","t":"足球裁判吹響了他那刺耳的金屬哨子，示意這場扣人心弦的冠軍賽結束。"},{"w":"wrap","p":"v./n.","d":"to cover or enclose something in paper or soft material","c":"包裝；包裹 (v.)；披肩；捲餅 (n.)","s":"The boutique sales assistant offered to wrap the delicate porcelain cup in elegant silk paper.","t":"精品店店員主動提出用優雅的絲棉紙把精緻的瓷杯包裝起來。"}]}];
